// App Store metadata read by `eas metadata:push` (eas.json points here).
//
// store.config.json is generated by scripts/store-metadata.mjs and committed.
// The App Review contact is personal, so it never enters the repo: set
// APPLE_REVIEW_CONTACT to {"firstName","lastName","email","phone"} as JSON
// when pushing. Without it, the review details are left as they are in
// App Store Connect.
const config = require('./store.config.json');

const contact = process.env.APPLE_REVIEW_CONTACT;
const { review, ...apple } = config.apple;

module.exports = {
  ...config,
  apple: contact ? { ...apple, review: { ...review, ...JSON.parse(contact) } } : apple,
};
